mapper.update:
        UPDATE cart
        SET quantity = #{quantity}
        WHERE member_id = #{member_id}
          AND product_id = #{productId};

        UPDATE cart
        SET quantity = quantity + 1
        WHERE member_id = #{member_id}
          AND product_id = #{productId};

        UPDATE cart
        SET quantity = quantity - 1
        WHERE member_id = #{member_id}
          AND product_id = #{productId}
          AND quantity > 1;

mapper.delete:
        DELETE FROM cart
        WHERE member_id = #{member_id}
          AND product_id = #{productId};
